const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], app=$('#app');
const state={page:'dashboard',data:null,contract:null,projectDetail:null,tab:'timeline',projectFilter:'',search:'',statusFilter:'',error:null,aggregate:{},workspaceProjectId:'',treeSearch:'',timelineZoom:'month',supplierDetailId:'',supplierDetailData:null,reportFilter:'all'};
const PAYMENT_DOC_TYPES=[['guarantee','Bảo lãnh'],['invoice','Invoice'],['packing_list','Packing list'],['dq','DQ'],['co','CO'],['cq','CQ'],['document_handover','Document handover'],['insurance','Bảo hiểm']];
const lcModeLabel=v=>v&&v!=='none'?'Có LC':'Không LC';
const lcStatusLabel=v=>({not_required:'Không yêu cầu',not_applicable:'Không áp dụng',preparing:'Đang chuẩn bị',submitted:'Đã gửi hồ sơ',opened:'LC đã mở',completed:'Hoàn tất LC'})[v]||v||'Không yêu cầu';
const lcStatusOf=x=>x?.contract_lc_status||x?.lc_status||'not_required';
const lcApplied=x=>Number(x?.contract_use_lc??x?.use_lc??0);
const paymentDocsSummary=x=>{const total=Number(x.required_doc_count??x.requirements?.length??0),got=Number(x.received_doc_count??x.requirements?.filter(r=>Number(r.received)===1).length??0);return {total,got,missing:Math.max(0,total-got)}};
const paymentCondition=x=>x?.payment_condition||((x?.status==='paid')?'paid':paymentDocsSummary(x).missing?'missing_docs':lcApplied(x)&&!['opened','completed'].includes(lcStatusOf(x))?'waiting_lc':'ready');
const healthClass=x=>Number(x?.health_score||100)>=85?'good':Number(x?.health_score||100)>=65?'attention':'risk';
const healthLabel=x=>x?.health_label||(Number(x?.health_score||100)>=85?'Tốt':Number(x?.health_score||100)>=65?'Cần chú ý':'Rủi ro');
const actionColor=s=>['late','overdue','lc_expired'].includes(s)?'red':['soon','missing_docs','waiting_lc','missing_contract_docs'].includes(s)?'orange':'blue';
