const money=n=>new Intl.NumberFormat('vi-VN',{maximumFractionDigits:0}).format(Number(n||0))+' ₫';
const shortMoney=n=>{n=Number(n||0);if(n>=1e9)return (n/1e9).toFixed(n>=1e11?1:2).replace(/\.00$/,'')+' Tỷ';if(n>=1e6)return (n/1e6).toFixed(1).replace(/\.0$/,'')+' Tr';return money(n)};
const date=v=>{if(!v)return '';const m=String(v).match(/^(\d{4})-(\d{2})-(\d{2})/);return m?`${m[3]}/${m[2]}/${m[1]}`:String(v)};
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
