  const ds=Object.fromEntries((d.deliverySummary||[]).map(x=>[x.bucket,x.count])),ps=Object.fromEntries((d.paymentSummary||[]).map(x=>[x.bucket,x]));
  const paidPct=d.contractValue?Math.min(100,Number(d.paid||0)/Number(d.contractValue)*100):0;
  const actionSeverity=x=>actionColor(x.status);
