      <div class="today-list">${actions.length?actions.map(x=>`<button class="today-row" data-contract="${x.contract_id}"><span class="task-kind ${actionSeverity(x)}">${x.kind==='payment'?'₫':'↧'}</span><span class="task-main"><b>${esc(x.title||actionLabel(x))}</b><small>${esc(x.contract_no)} · ${esc(x.project_name||'')} · ${esc(x.supplier_name||'')}</small></span><span class="task-date"><b>${date(x.due_date)}</b><small>${dayDiff(x.due_date)}</small></span><span>${badge(x.status)}</span><strong>${x.kind==='payment'?shortMoney(x.amount||0):actionLabel(x)}</strong></button>`).join(''):'<div class="empty">Không có công việc quá hạn hoặc sắp đến hạn trong 14 ngày.</div>'}</div>
