      <div class="project-health-dashboard">${ph.length?ph.map(x=>{const qp=Number(x.total_quantity||0)?Math.min(100,Number(x.received_quantity||0)/Number(x.total_quantity)*100):0,pp=Number(x.contract_value||0)?Math.min(100,Number(x.paid_amount||0)/Number(x.contract_value)*100):0,r=Number(x.late_deliveries||0)+Number(x.overdue_payments||0);return `<button class="dash-project-row ${r?'risk':''}" data-projectoverview="${x.id}"><span class="dash-project-title"><b>${esc(x.name)}</b><small>${x.contract_count||0} hợp đồng · ${shortMoney(x.contract_value||0)}</small></span><span class="dash-project-bars"><em>Hàng <i><b style="width:${qp}%"></b></i><strong>${Math.round(qp)}%</strong></em><em>TT <i><b style="width:${pp}%"></b></i><strong>${Math.round(pp)}%</strong></em></span><span class="dash-project-risk">${r?`<b>${r}</b><small>cảnh báo</small>`:'<b class="okmark">✓</b><small>ổn định</small>'}</span></button>`}).join(''):'<div class="empty">Chưa có dữ liệu dự án.</div>'}</div>
