function statusFilters(type){return `<div class="filterchips">${type==='delivery'?'<span class="chip red">Trễ hạn ưu tiên đầu</span><span class="chip orange">Sắp đến hạn ≤ 7 ngày</span>':'<span class="chip red">Quá hạn ưu tiên đầu</span><span class="chip orange">Sắp đến hạn ≤ 7 ngày</span>'}</div>`}
function deliveriesPage(){const rows=state.aggregate.deliveries||[];const byContract=new Map();rows.forEach(x=>{if(!byContract.has(x.contract_id))byContract.set(x.contract_id,{id:x.contract_id,contract_no:x.contract_no,name:x.contract_name||'',project_name:x.project_name,supplier_name:x.supplier_name,deliveries:[]});byContract.get(x.contract_id).deliveries.push(x)});return `${pageHead('THEO DÕI','Lịch / Leadtime','Tổng hợp mốc giao hàng, số lượng dự kiến và số lượng thực nhận.')} ${statusFilters('delivery')}<div class="leadtime-visual card"><div class="section-title"><div><h3>Tiến độ giao hàng trực quan</h3><div class="muted">Mỗi thanh biểu diễn các mốc giao của một hợp đồng; phần trăm bên phải là tiến độ nhận hàng.</div></div></div>${[...byContract.values()].length?[...byContract.values()].slice(0,10).map(c=>{const sorted=c.deliveries.filter(x=>x.planned_date).sort((a,b)=>(isoMs(a.planned_date)||0)-(isoMs(b.planned_date)||0));if(!sorted.length)return '';const times=sorted.map(x=>isoMs(x.planned_date)),min=Math.min(...times),max=Math.max(...times),range=Math.max(86400000,max-min),plan=sorted.reduce((a,x)=>a+Number(x.planned_quantity||0),0),rec=sorted.reduce((a,x)=>a+Number(x.received_quantity||0),0),progress=plan?Math.min(100,rec/plan*100):0;return `<div class="gantt-row enhanced"><div class="gantt-label"><span class="link" data-contract="${c.id}">${esc(c.contract_no)}</span><small>${esc(c.project_name||'')}</small></div><div><div class="gantt-track"><div class="gantt-line"></div>${sorted.map(x=>{const pos=((isoMs(x.planned_date)-min)/range)*100,st=x.computed_status||x.status,cls=st==='late'?'late':st==='soon'?'soon':st==='done'?'done':'future';return `<span class="gantt-point ${cls}" style="left:${pos}%" title="${esc(x.title)} · ${date(x.planned_date)} · ${qty(x.received_quantity)}/${qty(x.planned_quantity)}"></span>`}).join('')}</div><div class="delivery-progress-line"><i style="width:${progress}%"></i></div></div><div class="gantt-end"><b>${Math.round(progress)}%</b><small>${qty(rec)}/${qty(plan)}</small></div></div>`}).join(''):'<div class="empty">Chưa có mốc giao hàng.</div>'}</div><div class="card"><div class="tablewrap"><table class="table"><thead><tr><th>Tình trạng</th><th>Kế hoạch</th><th>Mốc giao</th><th>Hợp đồng</th><th>Dự án</th><th>NCC</th><th>Mặt hàng</th><th>SL kế hoạch</th><th>Đã nhận</th><th>Thực tế</th><th>Ghi chú</th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td>${badge(x.computed_status)}</td><td><b>${date(x.planned_date)}</b></td><td>${esc(x.title)}</td><td><span class="link" data-contract="${x.contract_id}">${esc(x.contract_no)}</span></td><td>${esc(x.project_name)}</td><td>${esc(x.supplier_name||'')}</td><td>${x.item_count||0}</td><td>${qty(x.planned_quantity)}</td><td><b>${qty(x.received_quantity)}</b></td><td>${date(x.actual_date)}</td><td>${esc(x.note||'')}</td></tr>`).join(''):'<tr><td colspan="11" class="empty">Chưa có mốc giao hàng.</td></tr>'}</tbody></table></div></div>`}
function paymentsPage(){const rows=state.aggregate.payments||[],total=rows.reduce((a,b)=>a+Number(b.amount||0),0),paid=rows.filter(x=>x.status==='paid').reduce((a,b)=>a+Number(b.amount||0),0),missing=rows.reduce((a,x)=>a+Math.max(0,Number(x.required_doc_count||0)-Number(x.received_doc_count||0)),0),lcOpen=rows.filter(x=>lcApplied(x)&&x.lc_status!=='completed').length;return `${pageHead('THEO DÕI','Thanh toán','Tổng hợp nghĩa vụ thanh toán, hồ sơ yêu cầu và LC của tất cả hợp đồng.')}<div class="subcards"><div class="mini big"><span>Tổng nghĩa vụ</span><b>${shortMoney(total)}</b></div><div class="mini big"><span>Đã thanh toán</span><b>${shortMoney(paid)}</b></div><div class="mini big"><span>Hồ sơ còn thiếu</span><b class="${missing?'warntext':''}">${missing}</b></div><div class="mini big"><span>LC chưa hoàn tất</span><b class="${lcOpen?'warntext':''}">${lcOpen}</b></div></div>${statusFilters('payment')}<div class="card"><div class="tablewrap"><table class="table payment-table"><thead><tr><th>Tình trạng</th><th>Hạn TT</th><th>Đợt</th><th>Hợp đồng</th><th>Dự án</th><th>NCC</th><th>%</th><th>Số tiền</th><th>Hồ sơ</th><th>LC</th><th>Ngày TT</th></tr></thead><tbody>${rows.length?rows.map(x=>{const ds=paymentDocsSummary(x);return `<tr><td>${badge(x.computed_status)}</td><td><b>${date(x.due_date)}</b></td><td>${esc(x.title)}</td><td><span class="link" data-contract="${x.contract_id}">${esc(x.contract_no)}</span></td><td>${esc(x.project_name)}</td><td>${esc(x.supplier_name||'')}</td><td>${x.percent||0}%</td><td><b>${money(x.amount)}</b></td><td><div class="payment-doc-summary ${ds.missing?'payment-doc-missing':'payment-doc-ok'}"><b>${ds.total?`${ds.got}/${ds.total}`:'—'}</b><small>${ds.total?(ds.missing?`Thiếu ${ds.missing}`:'Đủ'):'Chưa chọn'}</small></div></td><td>${lcApplied(x)?`<div class="lc-chip ${lcStatusOf(x)==='completed'?'done':'active'}"><b>LC</b><small>${lcStatusLabel(lcStatusOf(x))}</small></div>`:'—'}</td><td>${date(x.paid_date)}</td></tr>`}).join(''):'<tr><td colspan="11" class="empty">Chưa có đợt thanh toán.</td></tr>'}</tbody></table></div></div>`}
