    const saved=await api(c?'/api/du-an/contracts/'+c.id:'/api/du-an/contracts',{method:c?'PUT':'POST',headers:jsonHeaders,body:JSON.stringify(obj)});await reload(false);state.contract=saved;state.workspaceProjectId=saved.project_id||'';state.page='workspace';render();toast(c?'Đã cập nhật hợp đồng':'Đã thêm hợp đồng')
