async function filterContracts(){const u=new URL('/api/du-an/contracts',location.origin);if(state.search)u.searchParams.set('search',state.search);if(state.projectFilter)u.searchParams.set('project',state.projectFilter);if(state.statusFilter)u.searchParams.set('status',state.statusFilter);state.data.contracts=await api(u.pathname+u.search);render()}
function exportCSV(){const rows=[['Số hợp đồng','Tên hợp đồng','Dự án','Nhà cung cấp','Ngày hợp đồng','Giá trị','Đã thanh toán','Trạng thái'],...(state.data.contracts||[]).map(c=>[c.contract_no,c.name,c.project_name,c.supplier_name||'',c.signed_date||'',c.value_after_vat||0,c.paid_amount||0,c.status])];const csv='\ufeff'+rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`hop-dong-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href)}
function downloadCSV(name,rows){const csv='\ufeff'+rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`${name}-${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportReportCSV(type){const r=state.aggregate.reports||{};if(type==='contracts')return downloadCSV('bao-cao-hop-dong',[['Số HĐ','Tên HĐ','Dự án','NCC','Giá trị','Đã TT','Health','Giao trễ','TT quá hạn','HS thiếu','LC hết hạn'],...(r.contracts||[]).map(x=>[x.contract_no,x.name,x.project_name,x.supplier_name,x.value_after_vat,x.paid_amount,x.health_score,x.late_deliveries,x.overdue_payments,x.missing_payment_docs,x.lc_expired])]);if(type==='payments')return downloadCSV('bao-cao-thanh-toan',[['Hợp đồng','Đợt','Dự án','NCC','%','Số tiền','Hạn TT','Trạng thái','Điều kiện TT','HS đủ','HS yêu cầu','LC'],...(r.payments||[]).map(x=>[x.contract_no,x.title,x.project_name,x.supplier_name,x.percent,x.amount,x.due_date,x.computed_status,x.payment_condition,x.received_doc_count,x.required_doc_count,x.contract_use_lc?'Có':'Không'])]);if(type==='missing')return downloadCSV('ho-so-thanh-toan-thieu',[['Hợp đồng','Đợt','Hồ sơ thiếu','Hạn TT','Dự án','NCC','Số tiền'],...(r.missingRequirements||[]).map(x=>[x.contract_no,x.payment_title,x.document_label,x.due_date,x.project_name,x.supplier_name,x.amount])]);if(type==='lc')return downloadCSV('bao-cao-lc',[['Hợp đồng','Dự án','NCC','% LC','Số tiền LC','Số LC','Trạng thái','Ngày mở','Hết hạn','Số đợt áp dụng'],...(r.lc||[]).map(x=>[x.contract_no,x.project_name,x.supplier_name,x.lc_percent,x.lc_amount,x.lc_no,x.lc_status,x.lc_open_date,x.lc_expiry_date,x.payment_count])]);if(type==='suppliers')return downloadCSV('ncc-performance',[['NCC','Số HĐ','Giá trị','Dự án','Mốc giao hoàn thành','Đúng hạn %','Giao trễ','TT quá hạn','Performance'],...(r.suppliers||[]).map(x=>[x.name,x.contract_count,x.contract_value,x.project_count,x.completed_deliveries,Math.round(Number(x.on_time_rate||0)),x.late_deliveries,x.overdue_payments,Math.round(Number(x.performance_score||0))])])}

load();

function errorScreen(){return `<div class="app-error-screen"><div class="app-error-card"><div class="app-error-icon">!</div><h2>Không kết nối được hệ thống</h2><p>Không tải được dữ liệu từ Cloudflare Worker / D1.</p><code>${esc(state.error||'Lỗi không xác định')}</code><button class="btn primary" id="retryLoad">↻ Thử lại</button></div></div>`}

/* ===== v8 Workspace UI ===== */
function workspaceTree(){
  const projects=state.data?.projects||[], contracts=state.data?.contracts||[];
  const q=(state.treeSearch||'').trim().toLowerCase();
  const visible=projects.map(p=>({p,cs:contracts.filter(c=>c.project_id===p.id).filter(c=>!q||[c.contract_no,c.name,c.supplier_name,p.name].join(' ').toLowerCase().includes(q))})).filter(x=>!q||x.p.name.toLowerCase().includes(q)||x.cs.length);
  return `<div class="ws-tree-head"><b>DỰ ÁN / HỢP ĐỒNG</b><button class="ws-iconbtn" id="newProject" title="Thêm dự án">＋</button></div>
  <div class="ws-tree-search"><input id="treeSearch" placeholder="Tìm dự án, hợp đồng..." value="${esc(state.treeSearch||'')}"></div>
  <div class="ws-tree-list">${visible.map(({p,cs})=>{
    const all=contracts.filter(c=>c.project_id===p.id); const risk=all.filter(c=>Number(c.late_deliveries||0)+Number(c.overdue_payments||0)>0).length;
    const active=state.workspaceProjectId===p.id&&!state.contract;
    return `<div class="ws-project-block"><button class="ws-project-row ${active?'active':''}" data-wsproject="${p.id}"><span class="ws-chevron">⌄</span><span class="ws-project-name"><b>${esc(p.name)}</b><small>${all.length} hợp đồng${risk?` · ${risk} cảnh báo`:''}</small></span>${risk?'<i class="ws-alertdot"></i>':''}</button>
      <div class="ws-contract-children">${cs.map(c=>{const r=Number(c.late_deliveries||0)+Number(c.overdue_payments||0);const soon=Number(c.soon_deliveries||0)+Number(c.soon_payments||0);return `<button class="ws-contract-row ${state.contract?.id===c.id?'active':''}" data-wscontract="${c.id}"><span class="ws-contract-code">${esc(c.contract_no)}</span><span class="ws-contract-name">${esc(c.name||'')}</span>${r?'<i class="ws-status red" title="Có mốc trễ"></i>':soon?'<i class="ws-status orange" title="Có mốc sắp hạn"></i>':'<i class="ws-status green"></i>'}</button>`}).join('')||'<div class="ws-tree-empty">Chưa có hợp đồng</div>'}</div></div>`
  }).join('')||'<div class="ws-tree-empty">Không tìm thấy dữ liệu.</div>'}</div>
  <div class="ws-tree-status"><span>D1</span><i>+</i><span>R2</span></div>`;
}
function workspaceActions(){
  let actions=[];
  if(state.contract){
    actions=contractEvents(state.contract).filter(e=>['late','overdue','soon'].includes(e.status)).map(e=>({title:e.title,date:e.date,status:e.status,sub:e.sub,kind:e.kind}));
    for(const pm of state.contract.payments||[]){const ds=paymentDocsSummary(pm);if(pm.status!=='paid'&&ds.missing)actions.push({title:`${pm.title}: thiếu ${ds.missing} hồ sơ`,date:pm.due_date,status:'missing_docs',sub:`${ds.got}/${ds.total} hồ sơ · ${shortMoney(pm.amount)}`,kind:'document'});if(pm.status!=='paid'&&lcApplied(pm)&&paymentCondition(pm)==='waiting_lc')actions.push({title:`${pm.title}: chờ LC`,date:pm.due_date,status:'waiting_lc',sub:lcStatusLabel(lcStatusOf(pm)),kind:'payment'});if(pm.status!=='paid'&&paymentCondition(pm)==='lc_expired')actions.push({title:`${pm.title}: LC hết hạn`,date:state.contract.lc_expiry_date,status:'lc_expired',sub:`LC ${state.contract.lc_no||''}`,kind:'payment'})}
    if((state.contract.documents||[]).length===0)actions.push({title:'Hợp đồng chưa có chứng từ',date:'',status:'missing_contract_docs',sub:'Tải hợp đồng/phụ lục lên R2',kind:'document'});
  }else actions=(state.data?.dashboard?.actions||[]).map(a=>({title:a.title,date:a.due_date,status:a.status,sub:`${a.contract_no||''} · ${a.project_name||''}${a.missing_count?` · thiếu ${a.missing_count} HS`:''}`,kind:a.kind,contract_id:a.contract_id}));
  const rank={late:0,overdue:0,lc_expired:0,missing_docs:1,waiting_lc:1,soon:2,missing_contract_docs:3};actions.sort((a,b)=>(rank[a.status]??9)-(rank[b.status]??9)||String(a.date||'9999').localeCompare(String(b.date||'9999')));
  return `<div class="ws-action-head"><div><b>CẦN XỬ LÝ</b><small>${actions.length?`${actions.length} việc ưu tiên`:'Không có cảnh báo'}</small></div></div><div class="ws-action-list">${actions.slice(0,10).map(a=>`<button class="ws-action ${actionColor(a.status)}" ${a.contract_id?`data-wscontract="${a.contract_id}"`:''}><span class="ws-action-icon">${a.kind==='payment'?'₫':a.kind==='delivery'?'↧':a.kind==='document'?'▧':a.kind==='lc'?'LC':'!'}</span><span><b>${esc(a.title)}</b><small>${a.date?date(a.date)+' · ':''}${esc(a.sub||'')}</small></span></button>`).join('')||'<div class="ws-allgood"><span>✓</span><b>Không có việc gấp</b><small>Các mốc hiện tại đang trong kế hoạch.</small></div>'}</div>`;
}
function workspaceProject(){
  const p=(state.data?.projects||[]).find(x=>x.id===state.workspaceProjectId)||state.data?.projects?.[0];
  if(!p)return `<div class="ws-empty-main"><b>Chưa có dự án</b><span>Hãy tạo dự án đầu tiên để bắt đầu.</span><button class="btn primary" id="newProject">+ Tạo dự án</button></div>`;
  const cs=(state.data?.contracts||[]).filter(c=>c.project_id===p.id); const value=cs.reduce((a,c)=>a+Number(c.value_after_vat||0),0); const paid=cs.reduce((a,c)=>a+Number(c.paid_amount||0),0);
  const risk=cs.reduce((a,c)=>a+Number(c.late_deliveries||0)+Number(c.overdue_payments||0),0);
  return `<div class="ws-main-head"><div><div class="eyebrow">DỰ ÁN</div><h2>${esc(p.name)}</h2><p>${esc(p.code||'')} ${p.description?'· '+esc(p.description):''}</p></div><div class="actions"><button class="btn" data-projectoverview="${p.id}">Tổng quan chi tiết</button><button class="btn" data-projecttimeline="${p.id}">Timeline toàn dự án</button><button class="btn primary" id="newContract">+ Hợp đồng</button></div></div>
  <div class="ws-kpi-strip"><div><span>HỢP ĐỒNG</span><b>${cs.length}</b></div><div><span>TỔNG GIÁ TRỊ</span><b>${shortMoney(value)}</b></div><div><span>ĐÃ THANH TOÁN</span><b>${shortMoney(paid)}</b></div><div class="${risk?'danger':''}"><span>MỐC RỦI RO</span><b>${risk}</b></div></div>
  <div class="ws-project-panel"><div class="ws-section-title"><div><h3>Hợp đồng trong dự án</h3><p>Chọn một hợp đồng để mở workspace chi tiết.</p></div></div><div class="ws-project-contracts">${cs.map(c=>{const pct=Number(c.value_after_vat||0)?Math.min(100,Number(c.paid_amount||0)/Number(c.value_after_vat||1)*100):0;const r=Number(c.late_deliveries||0)+Number(c.overdue_payments||0);return `<button data-wscontract="${c.id}" class="ws-project-contract ${r?'risk':''}"><div><b>${esc(c.contract_no)}</b><span>${esc(c.name)}</span><small>${esc(c.supplier_name||'Chưa chọn NCC')}</small></div><div class="ws-project-contract-money"><b>${shortMoney(c.value_after_vat||0)}</b><span>TT ${pct.toFixed(0)}%</span></div><div class="ws-inline-progress"><i style="width:${pct}%"></i></div>${r?`<em>${r} cảnh báo</em>`:badge(c.status)}</button>`}).join('')||'<div class="empty">Dự án chưa có hợp đồng.</div>'}</div></div>`;
}
function workspaceContract(){
  const c=state.contract;if(!c)return workspaceProject();const paid=(c.payments||[]).filter(x=>x.status==='paid').reduce((a,b)=>a+Number(b.amount||0),0),tq=(c.items||[]).reduce((a,b)=>a+Number(b.quantity||0),0),rq=(c.items||[]).reduce((a,b)=>a+Number(b.received_quantity||0),0),dp=tq?Math.min(100,rq/tq*100):0,pp=Number(c.value_after_vat||0)?Math.min(100,paid/Number(c.value_after_vat||1)*100):0,missing=(c.payments||[]).reduce((a,x)=>a+paymentDocsSummary(x).missing,0);
  return `<div class="ws-main-head contract"><div><div class="eyebrow">${esc(c.project_name||'DỰ ÁN')} · HỢP ĐỒNG</div><h2>${esc(c.contract_no)} <span>${badge(c.status)}</span> <span class="health-pill ${healthClass(c)}"><b>${c.health_score||100}</b><span>${healthLabel(c)}</span></span></h2><p>${esc(c.name)}</p><div class="ws-supplier">NCC · <b>${esc(c.supplier_name||'Chưa chọn')}</b>${c.lc_mode&&c.lc_mode!=='none'?` <span class="lc-contract-badge">LC ${Number(c.lc_percent||0)}%</span>`:''}</div></div><div class="actions"><button class="btn" id="editContract">✎ Sửa HĐ</button><button class="btn primary" id="uploadDoc">＋ Chứng từ</button><button class="btn danger" id="deleteContract">Xóa</button></div></div>
  <div class="ws-kpi-strip contract"><div><span>GIÁ TRỊ HĐ</span><b>${shortMoney(c.value_after_vat||0)}</b></div><div><span>NHẬN HÀNG</span><b>${dp.toFixed(0)}%</b><small>${qty(rq)}/${qty(tq)}</small></div><div><span>THANH TOÁN</span><b>${pp.toFixed(0)}%</b><small>${shortMoney(paid)}</small></div><div class="${missing?'danger':''}"><span>HS THIẾU</span><b>${missing}</b></div><div><span>CHỨNG TỪ</span><b>${(c.documents||[]).length}</b></div></div>
  <div class="ws-timeline-panel">${timelineVisual(c)}</div><div class="ws-data-panel"><div class="ws-tabs">${[['items','Hàng hóa'],['deliveries','Giao hàng'],['payments','Thanh toán'],['documents','Chứng từ'],['audit','Lịch sử']].map(t=>`<button class="${state.tab===t[0]?'active':''}" data-tab="${t[0]}">${t[1]}${t[0]==='items'?` <span>${(c.items||[]).length}</span>`:t[0]==='audit'?` <span>${(c.audit_logs||[]).length}</span>`:''}</button>`).join('')}</div><div class="ws-tab-body">${tabContent(c)}</div></div>`;
}
function workspace(){ return state.contract?workspaceContract():workspaceProject(); }
function shell(inner){
  const nav=[
    ['dashboard','◫','Trang chủ'],
    ['projects','▣','Dự án'],
    ['contracts','▤','Hợp đồng'],
    ['suppliers','♟','Nhà cung cấp']
  ];
  const primarySidebar=`<aside class="sidebar primary-sidebar">
    <div class="brand"><span class="logo">PC</span><span>PROJECT CONTRACT<small>Quản lý hợp đồng dự án</small></span></div>
    <div class="navtitle">QUẢN LÝ</div>
    ${nav.map(n=>`<button class="navbtn ${state.page===n[0]?'active':''}" data-page="${n[0]}"><span class="navicon">${n[1]}</span>${n[2]}</button>`).join('')}
    <div class="navtitle">HỆ THỐNG</div>
    <button class="navbtn" id="backupBtn"><span class="navicon">⇩</span>Sao lưu dữ liệu</button>
    <div class="sidebar-foot"><div>Dữ liệu <b>D1</b> · File <b>R2</b></div><div class="connection">● Cloudflare connected</div></div>
  </aside>`;

  if(state.page==='workspace'){
    return `<div class="shell fixed-nav-shell">${primarySidebar}<main class="main fixed-nav-main">
      <header class="topbar workspace-global-topbar">
        <div class="topname">Project Contract Manager</div>
        <div class="ws-top-search"><span>⌕</span><input id="globalSearch" placeholder="Tìm nhanh hợp đồng, NCC..."></div>
        <div class="topright"><span class="access-actor">${esc(actorLabel())}</span><span class="top-pill">D1 + R2</span></div>
      </header>
      <section class="workspace-host">
        <div class="workspace-shell embedded-workspace">
          <aside class="workspace-tree">${workspaceTree()}</aside>
          <main class="workspace-main"><section class="workspace-content">${inner}</section></main>
          <aside class="workspace-actions">${workspaceActions()}</aside>
        </div>
      </section>
    </main></div>`;
  }

  return `<div class="shell fixed-nav-shell">${primarySidebar}<main class="main fixed-nav-main">
    <header class="topbar"><div class="topname">Project Contract Manager</div><div class="topright"><span class="access-actor">${esc(actorLabel())}</span><button class="btn small" data-page="workspace">Mở Workspace</button><span class="top-pill">ONLINE</span></div></header>
    <section class="content">${inner}</section>
  </main></div>`;
}
async function openSupplier(id){
  state.supplierDetailId=id;
  try{state.supplierDetailData=await api(`/api/du-an/suppliers/${id}/detail`)}catch{state.supplierDetailData=null}
  state.page='supplier_detail';
  render();
}
async function openContract(id){
  state.contract=await api('/api/du-an/contracts/'+id);
  state.workspaceProjectId=state.contract.project_id||'';
  state.page='workspace';
  state.tab='items';
  render();
}

async function openWorkspaceProject(id){state.workspaceProjectId=id;state.contract=null;state.page='workspace';render()}
function bind(){
  bindCore();
  $$('[data-wscontract]').forEach(b=>b.onclick=()=>openContract(b.dataset.wscontract));
  $$('[data-wsproject]').forEach(b=>b.onclick=()=>openWorkspaceProject(b.dataset.wsproject));
  if($('#treeSearch'))$('#treeSearch').oninput=e=>{state.treeSearch=e.target.value;render()};
  if($('#globalSearch'))$('#globalSearch').onkeydown=e=>{if(e.key==='Enter'){state.page='contracts';state.search=e.target.value;filterContracts()}};
  if($('#dashboardSearch'))$('#dashboardSearch').onkeydown=e=>{if(e.key==='Enter'){state.page='contracts';state.search=e.target.value;filterContracts()}};
}
function render(){
  if(state.error){app.innerHTML=errorScreen();const retry=$('#retryLoad');if(retry)retry.onclick=load;return}
  let inner=state.page==='workspace'?workspace():state.page==='dashboard'?dashboard():state.page==='contracts'?contracts():state.page==='projects'?projects():state.page==='suppliers'?suppliers():state.page==='supplier_detail'?supplierDetailPage():state.page==='deliveries'?deliveriesPage():state.page==='payments'?paymentsPage():state.page==='documents'?documentsPage():state.page==='reports'?reports():state.page==='project_overview'?projectOverviewPage():state.page==='project_detail'?projectTimelinePage():'';
  app.innerHTML=shell(inner);bind();
}
